//! TEMPORARY research probe for 2026-11-16-error-text-in-the-answer — not a check, removed after
//! its reading. Measures the lengths of the records, panics and errors an acting step causes on
//! the stand and on real-failure fixtures, and whether an app's own error boundary can be read.

use std::cell::RefCell;
use std::fmt;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::sync::{Arc, Mutex};

use accesskit::Role;
use blitz_test_harness::Harness;
use dioxus::prelude::*;
use dioxus_core::{CapturedError, ErrorContext, provide_create_error_boundary};
use dioxus_native_dom::{DioxusDocument, SnapshotNode};
use seven_guis::stand::{self, LeanTask};
use tracing::field::{Field, Visit};
use tracing::span::{Attributes, Id, Record};
use tracing::{Event, Metadata, Subscriber};

mod fixtures;

#[derive(Clone, Debug)]
struct Rec {
    target: String,
    level: String,
    message: String,
    fields: Vec<(String, String)>,
    file: Option<String>,
    line: Option<u32>,
}

#[derive(Clone, Default)]
struct Recorder {
    events: Arc<Mutex<Vec<Rec>>>,
    spans: Arc<Mutex<u64>>,
}

struct Values<'a>(&'a mut Rec);

impl Visit for Values<'_> {
    fn record_debug(&mut self, field: &Field, value: &dyn fmt::Debug) {
        if field.name() == "message" {
            self.0.message = format!("{value:?}");
        } else {
            self.0
                .fields
                .push((field.name().to_string(), format!("{value:?}")));
        }
    }
    fn record_str(&mut self, field: &Field, value: &str) {
        if field.name() == "message" {
            self.0.message = value.to_string();
        } else {
            self.0
                .fields
                .push((field.name().to_string(), value.to_string()));
        }
    }
}

impl Subscriber for Recorder {
    fn enabled(&self, _: &Metadata<'_>) -> bool {
        true
    }
    fn new_span(&self, _: &Attributes<'_>) -> Id {
        let mut n = self.spans.lock().unwrap_or_else(|e| e.into_inner());
        *n += 1;
        Id::from_u64(*n)
    }
    fn record(&self, _: &Id, _: &Record<'_>) {}
    fn record_follows_from(&self, _: &Id, _: &Id) {}
    fn event(&self, event: &Event<'_>) {
        let m = event.metadata();
        let mut rec = Rec {
            target: m.target().to_string(),
            level: m.level().to_string(),
            message: String::new(),
            fields: Vec::new(),
            file: m.file().map(str::to_string),
            line: m.line(),
        };
        event.record(&mut Values(&mut rec));
        self.events
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push(rec);
    }
    fn enter(&self, _: &Id) {}
    fn exit(&self, _: &Id) {}
}

thread_local! {
    static PANICS: RefCell<Vec<(String, String, u32, u32)>> = const { RefCell::new(Vec::new()) };
}

fn install_hook() {
    let previous = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let payload = info
            .payload_as_str()
            .unwrap_or("<non-string payload>")
            .to_string();
        let (file, line, col) = info.location().map_or(("?".to_string(), 0, 0), |l| {
            (l.file().to_string(), l.line(), l.column())
        });
        PANICS.with(|p| p.borrow_mut().push((payload, file, line, col)));
        let _ = &previous;
    }));
}

/// One step: run it under the recorder, catching a panic.
fn step(
    label: &str,
    harness: &mut Harness<DioxusDocument>,
    f: impl FnOnce(&mut Harness<DioxusDocument>),
) {
    let recorder = Recorder::default();
    PANICS.with(|p| p.borrow_mut().clear());
    let panicked = tracing::subscriber::with_default(recorder.clone(), || {
        let a = catch_unwind(AssertUnwindSafe(|| f(harness))).is_err();
        let b = catch_unwind(AssertUnwindSafe(|| {
            let _ = harness.settle();
        }))
        .is_err();
        a || b
    });
    let events = recorder
        .events
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .clone();
    let panics = PANICS.with(|p| p.borrow().clone());
    println!(
        "STEP {label} · events {} · panics {} · panicked {panicked}",
        events.len(),
        panics.len()
    );
    for e in &events {
        let fields: Vec<String> = e
            .fields
            .iter()
            .map(|(n, v)| format!("{n}={}B", v.len()))
            .collect();
        let shown: String = e.message.chars().take(160).collect();
        println!(
            "  EVENT {} {} msg={}B fields=[{}] at={}:{} :: {}",
            e.level,
            e.target,
            e.message.len(),
            fields.join(","),
            e.file.clone().unwrap_or_default(),
            e.line.unwrap_or(0),
            shown.replace('\n', "\\n")
        );
        for (n, v) in &e.fields {
            let v: String = v.chars().take(160).collect();
            println!("    FIELD {n} = {}", v.replace('\n', "\\n"));
        }
    }
    for (payload, file, line, col) in &panics {
        println!(
            "  PANIC payload={}B loc={}B {file}:{line}:{col} :: {}",
            payload.len(),
            format!("{file}:{line}:{col}").len(),
            payload.replace('\n', "\\n")
        );
    }
    let mark = harness.doc.root_error_mark();
    if let Some(cx) = harness
        .doc
        .vdom
        .runtime()
        .has_context::<ErrorContext>(ScopeId::ROOT_ERROR_BOUNDARY)
        && let Some(err) = cx.error()
    {
        let top = err.to_string();
        let alt = format!("{err:#}");
        let chain: Vec<String> = err.chain().map(|c| c.to_string()).collect();
        println!(
            "  ROOT ERROR top={}B alt={}B chain_len={} chain_bytes={} :: {} || {}",
            top.len(),
            alt.len(),
            chain.len(),
            chain.iter().map(String::len).sum::<usize>(),
            top,
            alt
        );
    }
    let _ = mark;
    OWN_BOUNDARIES.with(|b| {
        for (i, cx) in b.borrow().iter().enumerate() {
            if let Some(err) = cx.error() {
                let chain: Vec<String> = err.chain().map(|c| c.to_string()).collect();
                println!(
                    "  OWN BOUNDARY {i} error top={}B chain_len={} :: {}",
                    err.to_string().len(),
                    chain.len(),
                    format!("{err:#}")
                );
            }
        }
    });
}

thread_local! {
    static OWN_BOUNDARIES: RefCell<Vec<ErrorContext>> = const { RefCell::new(Vec::new()) };
}

fn walk<'a>(node: &'a SnapshotNode, out: &mut Vec<&'a SnapshotNode>) {
    out.push(node);
    for c in &node.children {
        walk(c, out);
    }
}

fn drive_screen(label: &str, harness: &mut Harness<DioxusDocument>) {
    let snap = harness.doc.snapshot();
    let mut nodes = Vec::new();
    for r in &snap.roots {
        walk(r, &mut nodes);
    }
    let targets: Vec<(String, Role, f32, f32)> = nodes
        .iter()
        .filter(|n| {
            matches!(
                n.role,
                Role::Button
                    | Role::TextInput
                    | Role::ComboBox
                    | Role::ListBoxOption
                    | Role::Slider
                    | Role::CheckBox
                    | Role::RadioButton
                    | Role::ListBox
            )
        })
        .map(|n| {
            (
                n.id.clone(),
                n.role,
                (n.bounds.x + n.bounds.width / 2.0) as f32,
                (n.bounds.y + n.bounds.height / 2.0) as f32,
            )
        })
        .collect();
    for (id, role, x, y) in targets {
        step(&format!("{label} click {id} {role:?}"), harness, |h| {
            h.click_at(x, y)
        });
        if role == Role::TextInput {
            step(&format!("{label} type {id}"), harness, |h| {
                h.type_text("ab12")
            });
        }
    }
}

