#[derive(Debug)]
struct SettingsError {
    key: &'static str,
    source: std::num::ParseIntError,
}

impl fmt::Display for SettingsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "invalid value for setting `{}`", self.key)
    }
}

impl std::error::Error for SettingsError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.source)
    }
}

#[derive(Debug)]
struct LoadError {
    source: SettingsError,
}

impl fmt::Display for LoadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "could not load the booking form")
    }
}

impl std::error::Error for LoadError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.source)
    }
}

fn parse_seats(text: &str) -> Result<u32, LoadError> {
    text.parse::<u32>().map_err(|source| LoadError {
        source: SettingsError {
            key: "seats",
            source,
        },
    })
}

fn index_past_end() {
    let rows: Vec<u32> = Vec::new();
    let picked = rows[3];
    let _ = picked;
}

fn unwrap_parse() {
    let n: u32 = "twelve".parse().unwrap();
    let _ = n;
}

fn factory() -> ErrorContext {
    let cx = ErrorContext::new(None);
    OWN_BOUNDARIES.with(|b| b.borrow_mut().push(cx.clone()));
    cx
}

fn failing_inner() -> Element {
    rsx! {
        button {
            id: "own-err",
            onclick: move |_| -> Result<(), CapturedError> {
                let n = parse_seats("4x")?;
                let _ = n;
                Ok(())
            },
            "Own boundary Err"
        }
    }
}

fn real_failures() -> Element {
    provide_create_error_boundary(factory);
    let mut s = use_signal(|| 0u32);
    rsx! {
        div { id: "fx",
            button { id: "idx", onclick: move |_| index_past_end(), "Index" }
            button { id: "unwrap", onclick: move |_| unwrap_parse(), "Unwrap" }
            button {
                id: "warn",
                onclick: move |_| tracing::warn!(seats = 4, password = "hunter2", "booking rejected: {} seats over the limit", 4),
                "Warn"
            }
            button { id: "count", onclick: move |_| s += 1, "{s}" }
            ErrorBoundary {
                handle_error: |_errors: ErrorContext| rsx! { div { id: "own-fallback", "Own fallback" } },
                failing_inner {}
            }
            button {
                id: "root-err",
                onclick: move |_| -> Result<(), CapturedError> {
                    let n = parse_seats("many")?;
                    let _ = n;
                    Ok(())
                },
                "Root Err"
            }
        }
    }
}

fn no_factory_app() -> Element {
    rsx! {
        div { id: "nf",
            ErrorBoundary {
                handle_error: |_errors: ErrorContext| rsx! { div { id: "own-fallback", "Own fallback" } },
                failing_inner {}
            }
        }
    }
}

fn render_writer() -> Element {
    let mut s = use_signal(|| 0u32);
    let mut go = use_signal(|| false);
    if go() {
        // A write during render: the framework warns.
        s += 1;
    }
    rsx! {
        div {
            button { id: "go", onclick: move |_| go.set(true), "Go {s}" }
        }
    }
}

