fn probe() {
    install_hook();
    // The stand.
    for task in LeanTask::ALL {
        let mut h = stand::boot(task, stand::options(false));
        let _ = h.settle();
        drive_screen(&format!("{task:?}"), &mut h);
        if task == LeanTask::Timer {
