    let mut nodes = Vec::new();
    for r in &snap.roots {
        walk(r, &mut nodes);
    }
    let cells: Vec<(String, f32, f32)> = nodes
        .iter()
        .filter(|n| n.role == Role::TextInput)
        .take(3)
        .map(|n| {
            (
                n.id.clone(),
                (n.bounds.x + n.bounds.width / 2.0) as f32,
                (n.bounds.y + n.bounds.height / 2.0) as f32,
            )
        })
        .collect();
    for (id, x, y) in cells {
