        step(&format!("Cells enter {id}"), &mut h, |h| {
            h.press(::keyboard_types::Key::Named(
                ::keyboard_types::NamedKey::Enter,
            ))
        });
    }
    let mut h = stand::boot_load(stand::options(false));
    for _ in 0..60 {
        if h.settle().is_ok() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
    drive_screen("Load", &mut h);

    // Real failures.
    let mut h = fixtures::boot(real_failures, false);
    let _ = h.settle();
    println!(
