        .is_some();
    println!("OWN fallback rendered: {fallback}");
    step("Fixture click root-err", &mut h, |h| h.click("#root-err"));

    // An app with its own boundary and no factory of its own: the factory provided at the
    // document's root scope before the build, as dioxus-native-dom would.
    OWN_BOUNDARIES.with(|b| b.borrow_mut().clear());
    let vdom = VirtualDom::new(no_factory_app);
    vdom.in_scope(ScopeId::ROOT, || provide_create_error_boundary(factory));
    let mut h = Harness::from_vdom(vdom, stand::options(false));
    let _ = h.settle();
    println!(
        "ROOT-INJECTED OWN BOUNDARIES registered at boot: {}",
        OWN_BOUNDARIES.with(|b| b.borrow().len())
    );
    step("Injected click own-err", &mut h, |h| h.click("#own-err"));
    let mark_root = h.doc.root_error_mark().is_some();
    println!("Injected: root boundary holds an error: {mark_root}");

    let mut h = fixtures::boot(render_writer, false);
    let _ = h.settle();
    step("Writer click go", &mut h, |h| h.click("#go"));
